import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../providers/app_state_provider.dart';
import '../services/fitness_repository.dart';
import '../widgets/custom_app_bar.dart';
import '../widgets/workout_card.dart';
class WorkoutScreen extends StatelessWidget { const WorkoutScreen({super.key}); @override Widget build(BuildContext context) { final repo = FitnessRepository(); final app = context.watch<AppStateProvider>(); return DefaultTabController(length: 7, child: Scaffold(appBar: const CustomAppBar(title: 'Workout Plan', subtitle: '90-day beginner muscle gain split'), body: Column(children: [TabBar(isScrollable: true, tabs: repo.workouts().map((w) => Tab(text: w.day.substring(0, 3))).toList()), Expanded(child: TabBarView(children: repo.workouts().map((day) => ListView(padding: const EdgeInsets.all(16), children: [Text(day.title, style: Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight: FontWeight.bold)), const SizedBox(height: 8), if (day.exercises.isEmpty) const Card(child: Padding(padding: EdgeInsets.all(24), child: Text('Rest, stretch, hydrate, and sleep well.'))) else ...day.exercises.map((e) => WorkoutCard(exercise: e, completed: app.completedWorkouts.contains('${day.day}-${e.name}'), onChanged: (_) => app.toggleWorkout('${day.day}-${e.name}'))), Card(child: ListTile(leading: const Icon(Icons.timer, color: Colors.amber), title: const Text('Workout Timer'), subtitle: const Text('Use 60-90 seconds between sets and keep form clean.'), trailing: FilledButton(onPressed: () {}, child: const Text('Start')))]).toList()))]))); } }
